from z3 import *
x = [[Bool("x_%s_%s" % (i, j)) for j in range(10)] for i in range(6)]
s = Solver()
for j in range(10):
    s.add(Sum([If(x[i][j], 1, 0) for i in range(6)]) == 3)
for i in range(6):
    s.add(Sum([If(x[i][j], 1, 0) for j in range(10)]) == 5)
for a in range(6):
    for b in range(a+1, 6):
        s.add(Sum([If(And(x[a][j], x[b][j]), 1, 0) for j in range(10)]) == 2)
print(s.check())
